<?php
$titulo_pagina='Minha trilha de aprendizagem'; $css_extra='study-tools.css'; $script_extra='study-path.js'; require_once '../includes/header.php';
$tema=trim((string)($_GET['preciso']??'')); $ja_sei=trim((string)($_GET['ja_sei']??'')); $nivel=(string)($_GET['nivel']??'iniciando');
$nivel=in_array($nivel,['iniciando','revisando','aprofundando'],true)?$nivel:'iniciando';
$categorias=$pdo->query('SELECT DISTINCT categoria FROM conteudos ORDER BY categoria')->fetchAll(PDO::FETCH_COLUMN);
$conteudos=$simulados=[]; $termosEncontrados=$formulasEncontradas=[]; $questoesPorConteudo=[];
if($tema!==''){
 $like='%'.$tema.'%';
 $stmt=$pdo->prepare('SELECT id,titulo,resumo,categoria FROM conteudos WHERE titulo LIKE :q1 OR resumo LIKE :q2 OR categoria LIKE :q3 ORDER BY titulo LIMIT 8');$stmt->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like]);$conteudos=$stmt->fetchAll();
 $termos=require '../includes/dictionary-data.php';$formulas=require '../includes/formula-data.php';
 $contains=static fn($text)=>mb_stripos($text,$tema,0,'UTF-8')!==false;
 $termosEncontrados=array_slice(array_values(array_filter($termos,fn($t)=>$contains($t['termo'].' '.$t['categoria'].' '.$t['definicao']))),0,4);
 $formulasEncontradas=array_slice(array_values(array_filter($formulas,fn($f)=>$contains($f['nome'].' '.$f['tema'].' '.$f['descricao']))),0,4);
 if($conteudos){$ids=array_map(static fn($item)=>(int)$item['id'],$conteudos);$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("SELECT conteudo_id,COUNT(*) AS total FROM questoes WHERE conteudo_id IN ($marks) AND tipo='multipla' GROUP BY conteudo_id");$stmt->execute($ids);foreach($stmt->fetchAll() as $row)$questoesPorConteudo[(int)$row['conteudo_id']]=(int)$row['total'];$stmt=$pdo->prepare("SELECT id,titulo,descricao,conteudo_id FROM simulados WHERE conteudo_id IN ($marks) ORDER BY id DESC");$stmt->execute($ids);$simulados=$stmt->fetchAll();}
}
$searchUrl='explorar.php?q='.rawurlencode($tema);$chatUrl='chat.php?tema='.rawurlencode($tema);
?>
