<?php if($tema!==''): ?><section class="path-results"><header class="path-results-heading"><div><span class="panel-eyebrow">SEU PLANO PARA</span><h2><?= escape($tema) ?></h2><?php if($ja_sei): ?><p>Partindo do que você já conhece: <strong><?= escape($ja_sei) ?></strong></p><?php endif; ?></div><span class="path-level"><?= $nivel==='iniciando'?'COMEÇANDO':($nivel==='revisando'?'REVISÃO E PRÁTICA':'DESAFIO') ?></span></header>
<div class="path-option-grid">
<?php if($conteudos): foreach($conteudos as $item): ?><article class="path-option path-option-featured"><span class="path-option-icon">▤</span><small>LEITURA · <?= escape($item['categoria']) ?></small><h3><?= escape($item['titulo']) ?></h3><p><?= escape($item['resumo']) ?></p><a href="conteudo.php?id=<?= (int)$item['id'] ?>">Ler conteúdo <b>→</b></a></article><?php endforeach; endif; ?>
<?php if($termosEncontrados): foreach($termosEncontrados as $item): ?><article class="path-option"><span class="path-option-icon pink">Aa</span><small>DICIONÁRIO · <?= escape($item['categoria']) ?></small><h3><?= escape($item['termo']) ?></h3><p><?= escape($item['definicao']) ?></p><a href="dicionario.php?q=<?= rawurlencode($item['termo']) ?>">Revisar conceito <b>→</b></a></article><?php endforeach; endif; ?>
<?php if($formulasEncontradas): foreach($formulasEncontradas as $item): ?><article class="path-option"><span class="path-option-icon">ƒ</span><small>FÓRMULA · <?= escape($item['tema']) ?></small><h3><?= escape($item['nome']) ?></h3><div class="path-formula"><?= escape($item['formula']) ?></div><p><?= escape($item['unidade']) ?></p><a href="formulas.php?q=<?= rawurlencode($item['nome']) ?>">Ver fórmula <b>→</b></a></article><?php endforeach; endif; ?>
<?php foreach($conteudos as $item): if(($questoesPorConteudo[(int)$item['id']]??0)>0): ?><article class="path-option"><span class="path-option-icon pink">✎</span><small>PRÁTICA · <?= (int)$questoesPorConteudo[(int)$item['id']] ?> QUESTÕES</small><h3>Teste o que aprendeu</h3><p>Responda questões de <?= escape($item['titulo']) ?> e receba feedback.</p><a href="quiz.php?conteudo=<?= (int)$item['id'] ?>">Começar quiz <b>→</b></a></article><?php endif; endforeach; ?>
<?php foreach($simulados as $item): ?><article class="path-option"><span class="path-option-icon pink">⚡</span><small>DESAFIO</small><h3><?= escape($item['titulo']) ?></h3><p><?= escape($item['descricao']??'Pratique esse assunto em um simulado.') ?></p><a href="simulado.php?id=<?= (int)$item['id'] ?>">Fazer simulado <b>→</b></a></article><?php endforeach; ?>
<article class="path-option"><span class="path-option-icon pink">✦</span><small>APOIO PERSONALIZADO</small><h3>Converse sobre esse tema</h3><p>Peça uma explicação, um exemplo ou ajuda para entender por onde começar.</p><a href="<?= escape($chatUrl) ?>">Perguntar no chat <b>→</b></a></article>
<article class="path-option"><span class="path-option-icon">⌕</span><small>OUTRAS OPÇÕES</small><h3>Explore mais recursos</h3><p>Busque questões, materiais, conceitos e fórmulas relacionados a “<?= escape($tema) ?>”.</p><a href="<?= escape($searchUrl) ?>">Ver resultados <b>→</b></a></article>
